```ts
import type { GeospatialCamera } from "@babylonjs/lite";

export function centerOnLatLon(camera: GeospatialCamera, latitudeDeg: number, longitudeDeg: number): void {
  const r = camera.limits.planetRadius;
  const lat = latitudeDeg * (Math.PI / 180);
  const lon = longitudeDeg * (Math.PI / 180);

  const center: GeospatialCamera["center"] = {
    x: r * Math.cos(lat) * Math.sin(lon),
    y: r * Math.sin(lat),
    z: r * Math.cos(lat) * Math.cos(lon),
  };

  camera._setOrientation(camera.yaw, camera.pitch, camera.radius, center);
}
```

I added `src/center-on.ts`, which converts the requested latitude/longitude to a point on the planet sphere and updates the camera’s centre while keeping its yaw, pitch, and radius unchanged. I wasn’t fully certain of Babylon Lite’s exact world-axis convention, so I used the Y-up convention implied by “lat 0, lon 0 is the new camera centre” and “heading 90° is east”: lat 0/lon 0 at +Z, north +Y, east +X.

